function parseCsv(text){const rows=[];let row=[],value='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++}else quoted=!quoted}else if(ch===','&&!quoted){row.push(value.trim());value=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(value.trim());if(row.some(cell=>cell!==''))rows.push(row);row=[];value=''}else value+=ch}row.push(value.trim());if(row.some(cell=>cell!==''))rows.push(row);return rows}
