const num=(r,k)=>{const raw=r?.[k];if(raw===undefined||raw===null||raw==='')return null;const x=Number(raw);return Number.isFinite(x)?x:null},clamp=x=>Math.max(0,Math.min(100,x)),mean=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:null;
