// Weekly public-news intelligence. Fetching is browser-side and snapshots are local to this browser.
const WEEKLY_KEY='nanovest-weekly-intelligence-v1',WEEK_MS=7*24*60*60*1000;
const WEEKLY_COMPANIES=[
 ['AAPL','Apple',['apple','iphone']],['MSFT','Microsoft',['microsoft','azure']],['NVDA','NVIDIA',['nvidia']],['GOOGL','Alphabet',['alphabet','google']],['AMZN','Amazon',['amazon','aws']],['META','Meta Platforms',['meta platforms','facebook']],['TSLA','Tesla',['tesla']],['AVGO','Broadcom',['broadcom']],['AMD','Advanced Micro Devices',['advanced micro devices']],['JPM','JPMorgan Chase',['jpmorgan','jp morgan']],['WMT','Walmart',['walmart']],['LLY','Eli Lilly',['eli lilly']],['NFLX','Netflix',['netflix']],['ORCL','Oracle',['oracle']],['BABA','Alibaba',['alibaba']],['005930.KS','Samsung Electronics',['samsung electronics']],['7203.T','Toyota Motor',['toyota motor','toyota']],['0700.HK','Tencent',['tencent']],['BBCA.JK','Bank Central Asia',['bank central asia','bca']],['BBRI.JK','Bank Rakyat Indonesia',['bank rakyat indonesia','bri']],['TLKM.JK','Telkom Indonesia',['telkom indonesia','telkomsel']],['GOTO.JK','GoTo Gojek Tokopedia',['goto group','gojek','tokopedia']],['ANTM.JK','Aneka Tambang',['antam','aneka tambang']],['ASII.JK','Astra International',['astra international']],['UNVR.JK','Unilever Indonesia',['unilever indonesia']]
];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function getWeeklyHistory(){try{return JSON.parse(localStorage.getItem(WEEKLY_KEY)||'[]')}catch{return[]}}
function when(value){return new Date(value).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})}
function renderWeekly(snapshot){if(!snapshot){$('#weekly-updated').textContent='No update yet';$('#weekly-status').textContent='No saved update';return}
 $('#weekly-updated').textContent=when(snapshot.updatedAt);$('#weekly-status').textContent=snapshot.items.length?`${snapshot.items.length} tracked ticker matches`:'No tracked companies found';$('#weekly-status').className='status '+(snapshot.items.length?'good':'');
 $('#weekly-summary').textContent=snapshot.summary||'This scan found no current company-specific headlines with enough evidence to rank an outlook. The sourced headlines below are retained for context.';
 $('#weekly-brief-body').innerHTML=snapshot.brief.length?`<ul>${snapshot.brief.map(n=>`<li><a href="${esc(n.url)}" target="_blank" rel="noopener">${esc(n.title)}</a><small>${esc(n.source)} · ${esc(when(n.publishedAt))}</small></li>`).join('')}</ul>`:'<p class="muted">No recent market headlines were returned by the public feed.</p>';
 $('#weekly-count').textContent=`Top ${snapshot.items.length} of up to 10 tracked tickers with related headlines`;
 $('#weekly-ticker-rows').innerHTML=snapshot.items.length?snapshot.items.map(x=>{const signalClass=x.outlook==='Bullish'?'bullish':x.outlook==='Bearish'?'bearish':'neutral';return `<tr><td><b>${esc(x.ticker)}</b></td><td>${esc(x.company)}</td><td>${esc(x.impact)}</td><td><span class="signal ${signalClass}">${esc(x.outlook)}</span></td><td>${x.sources.map(n=>`<a class="news-link" href="${esc(n.url)}" target="_blank" rel="noopener">${esc(n.title)}</a>`).join('<br>')}</td></tr>`}).join(''):'<tr><td colspan="5" class="muted">No current headlines matched a tracked company.</td></tr>';
}
function renderWeeklyHistory(selected='latest'){const history=getWeeklyHistory(),sel=$('#weekly-history-select');sel.innerHTML='<option value="latest">Latest update</option>'+history.map((x,i)=>`<option value="${i}">${esc(when(x.updatedAt))}</option>`).join('');sel.value=selected==='latest'?'latest':String(selected);const active=selected==='latest'?history[0]:history[Number(selected)];$('#weekly-history-list').innerHTML=history.length?history.map((x,i)=>`<button type="button" class="history-entry${active===x?' selected':''}" data-history-index="${i}"><strong>${esc(when(x.updatedAt))}</strong><span>${x.items.length} tickers · ${x.brief.length} linked headlines</span><small>${i===0?'Latest saved update':'Open saved update'}</small></button>`).join(''):'<p class="muted history-empty">No snapshots have been saved yet. A successful refresh will appear here.</p>';$$('.history-entry').forEach(b=>b.onclick=()=>renderWeeklyHistory(Number(b.dataset.historyIndex)));renderWeekly(active);$('#weekly-history-detail').textContent=active?`Viewing snapshot from ${when(active.updatedAt)}.`:'History is saved in this browser.'}
async function fetchWeeklyUpdate(force=false){const status=$('#weekly-status');status.textContent='Fetching company headlines…';status.className='status';try{
 const companies=WEEKLY_COMPANIES.map(x=>x[1]),groups=[];for(let i=0;i<companies.length;i+=4)groups.push(companies.slice(i,i+4));
 const queries=groups.map(group=>`(${group.map(name=>name.includes(' ')?`"${name}"`:name).join(' OR ')}) (stock OR shares OR earnings OR revenue OR profit OR guidance OR outlook) when:7d`);
 const feeds=await Promise.allSettled(queries.map(async q=>{const rss=new URL('https://news.google.com/rss/search');rss.searchParams.set('q',q);rss.searchParams.set('hl','en-US');rss.searchParams.set('gl','US');rss.searchParams.set('ceid','US:en');const endpoint=new URL('https://api.rss2json.com/v1/api.json');endpoint.searchParams.set('rss_url',rss.toString());const response=await fetch(endpoint,{cache:'no-store'});if(!response.ok)throw Error(`Public news service returned ${response.status}`);const result=await response.json();if(result.status!=='ok')throw Error(result.message||'Could not read a public news query');return result.items||[]}));
 const all=feeds.flatMap(x=>x.status==='fulfilled'?x.value:[]).map(item=>{const title=String(item.title||'').trim(),parts=title.split(' - '),published=new Date(item.pubDate||Date.now());return {title,url:String(item.link||'').trim(),source:String(item.author|| (parts.length>1?parts.pop().trim():'Google News')),publishedAt:(Number.isFinite(published.getTime())?published:new Date()).toISOString()}}).filter(n=>n.title&&n.url);
 if(!all.length)throw Error('No company news was returned by the public news service');const unique=[...new Map(all.map(n=>[n.url,n])).values()];
 const cutoff=Date.now()-WEEK_MS,news=unique.filter(n=>new Date(n.publishedAt).getTime()>=cutoff).sort((a,b)=>new Date(b.publishedAt)-new Date(a.publishedAt));const brief=news.slice(0,8);
 const positive=/\b(beat|beats|record|surge|surges|soar|soars|raise|raises|raised|upgrade|upgrades|profit|growth|approved|approval|wins|won|rally|rallies|rallied|rise|rises|rose|gain|gains|gained|climb|climbs|climbed|jump|jumps|jumped|higher|strong|outperform|outperformed|soared|boost|boosts)\b/i,negative=/\b(miss|misses|missed|cut|cuts|cutting|downgrade|downgrades|loss|losses|decline|declines|fall|falls|fell|drop|drops|dropped|plunge|plunges|plunged|tumble|tumbles|tumbled|slump|slumps|slumped|sink|sinks|sank|lower|investigation|probe|recall|recalls|layoff|layoffs|weak|warning|warns|lawsuit|fine|fined|selloff)\b/i;
 const map=new Map();for(const n of news){const title=n.title.toLowerCase();for(const [ticker,company,aliases] of WEEKLY_COMPANIES){if(!aliases.some(a=>new RegExp('\\b'+a+'\\b','i').test(title)))continue;const uncertain=/\?|\b(can|could|might|may|will)\b/i.test(title),pos=!uncertain&&positive.test(title),neg=!uncertain&&negative.test(title);const row=map.get(ticker)||{ticker,company,positive:0,negative:0,unclear:0,mentions:0,sources:[]};row.mentions++;if(pos&&!neg)row.positive++;else if(neg&&!pos)row.negative++;else row.unclear++;if(row.sources.length<4)row.sources.push(n);map.set(ticker,row)}}
 const items=[...map.values()].map(x=>({...x,outlook:x.positive>x.negative?'Bullish':x.negative>x.positive?'Bearish':x.positive+x.negative?'Mixed':'No clear signal',impact:`${x.mentions} related headline${x.mentions===1?'':'s'} · ${x.positive} bullish, ${x.negative} bearish, ${x.unclear} without a clear direction`})).sort((a,b)=>b.mentions-a.mentions||a.company.localeCompare(b.company)).slice(0,10);
 const bullish=items.filter(x=>x.outlook==='Bullish').length,bearish=items.filter(x=>x.outlook==='Bearish').length;const leading=items.slice(0,3).map(x=>`${x.company} (${x.outlook.toLowerCase()})`);const summary=items.length?`The scan reviewed ${news.length} unique, company-related headlines from the past seven days. The most-covered tracked companies were ${leading.join(', ')}. Across the top ${items.length}, ${bullish} showed more bullish than bearish headline signals and ${bearish} showed more bearish; mixed or non-directional coverage is labeled without assigning an outlook.`:`The scan reviewed ${news.length} company-related headlines from the past seven days but found no verified matches to the tracked ticker list, so no ticker impacts are shown.`;
 const snapshot={updatedAt:new Date().toISOString(),brief,items,summary};const old=getWeeklyHistory();const sameWeek=old[0]&&Date.now()-new Date(old[0].updatedAt).getTime()<WEEK_MS;const history=sameWeek&&!force&&old[0].summary?[snapshot,...old.slice(1)]:[snapshot,...old];localStorage.setItem(WEEKLY_KEY,JSON.stringify(history.slice(0,104)));renderWeeklyHistory('latest');$('#weekly-next').textContent=when(Date.now()+WEEK_MS);return true;
 }catch(error){status.textContent='News feed unavailable';status.className='status bad';$('#weekly-brief-body').innerHTML=`<p class="muted">${esc(error.message)}. Existing saved history is still available. Check browser internet access and try again.</p>`;return false}}
$('#weekly-history-select').onchange=e=>renderWeeklyHistory(e.target.value==='latest'?'latest':Number(e.target.value));$('#weekly-refresh').onclick=()=>fetchWeeklyUpdate(true).then(ok=>toast(ok?'Weekly intelligence refreshed':'Could not refresh the public news feed'));
(function initWeekly(){const history=getWeeklyHistory();renderWeeklyHistory('latest');if(history[0])$('#weekly-next').textContent=when(new Date(history[0].updatedAt).getTime()+WEEK_MS);if(!history[0]||!history[0].summary||Date.now()-new Date(history[0].updatedAt).getTime()>=WEEK_MS)fetchWeeklyUpdate(false)})();

function renderForwardUploads(){const grid=$('#forward-upload-grid');grid.innerHTML=Object.entries(schema).map(([key,c])=>{const file=forwardUploads[key],rows=file?.data;return `<article class="card upload-card"><div class="upload-head"><h3>${c.label} data</h3><span class="tag">${file?'READY':'EMPTY'}</span></div><div class="upload-body"><div class="upload-actions"><label class="file-label" for="forward-file-${key}">Upload CSV / Excel</label><input id="forward-file-${key}" class="forward-file-input" type="file" accept=".csv,.xlsx,.xls" data-forward-kind="${key}"><span class="file-name">${file?esc(file.name):'No file selected'}</span></div>${rows?`<div class="preview-title">INPUT PREVIEW · ${Math.max(0,rows.length-1)} records</div>${preview(rows)}`:'<p class="muted">Include a ticker or symbol column so records can be matched across all three data files.</p>'}</div></article>`}).join('');$$('.forward-file-input').forEach(input=>input.onchange=handleForwardFile)}
async function handleForwardFile(event){const file=event.target.files?.[0],kind=event.target.dataset.forwardKind;if(!file)return;try{let data;if(/\.csv$/i.test(file.name))data=parseCsv(await file.text());else{if(!window.XLSX)throw Error('Excel reader could not load. Please use CSV.');const workbook=XLSX.read(await file.arrayBuffer(),{type:'array'});data=XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]],{header:1,defval:''})}forwardUploads[kind]={name:file.name,data};forwardRecords=null;$('#forward-results').hidden=true;$('#forward-message').textContent=`${schema[kind].label} data loaded (${Math.max(0,data.length-1)} rows).`;renderForwardUploads();toast(`${schema[kind].label} data loaded`)}catch(error){toast(error.message)}}
function processForwardData(){if(!valid())return null;const rowsByKind={},tickerSets={};for(const kind of Object.keys(schema)){rowsByKind[kind]=rowsAsObjects(forwardUploads[kind]?.data);tickerSets[kind]=new Set(rowsByKind[kind].map(row=>String(row.ticker||row.symbol||'').trim().toUpperCase()).filter(Boolean))}const common=[...tickerSets.fundamental].filter(ticker=>tickerSets.technical.has(ticker)&&tickerSets.catalyst.has(ticker)).sort();if(!common.length)return null;const commonSet=new Set(common),savedUploads=uploads;try{uploads={};for(const kind of Object.keys(schema)){const rows=rowsByKind[kind].filter(row=>commonSet.has(String(row.ticker||row.symbol||'').trim().toUpperCase()));const headers=Object.keys(rows[0]||{});uploads[kind]={data:[headers,...rows.map(row=>headers.map(header=>row[header]??''))]}}const records=processSubmittedData();return records?.filter(record=>commonSet.has(record.ticker)).map(record=>({...record,actual:null,correct:false})).sort((a,b)=>b.composite-a.composite||a.ticker.localeCompare(b.ticker))||null}finally{uploads=savedUploads}}
function renderForwardResults(){const panel=$('#forward-results');if(!forwardRecords?.length){panel.hidden=true;return}panel.hidden=false;const bullish=forwardRecords.filter(r=>r.signal==='Bullish').length,bearish=forwardRecords.filter(r=>r.signal==='Bearish').length,neutral=forwardRecords.length-bullish-bearish;$('#forward-metrics').innerHTML=[['Tickers',forwardRecords.length,'Matched across all three input files'],['Bullish',bullish,'At or above the configured cutoff'],['Bearish',bearish,'At or below the configured cutoff'],['Neutral',neutral,'Between configured cutoffs']].map(x=>`<div class="card metric"><span>${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('');$('#forward-record-count').textContent=`${forwardRecords.length} signals`;$('#forward-evaluation-body').innerHTML=forwardRecords.map(r=>`<tr><td><b>${esc(r.ticker)}</b></td><td class="num">${Number(r.fundamental).toFixed(1)}</td><td class="num">${Number(r.technical).toFixed(1)}</td><td class="num">${Number(r.catalyst).toFixed(1)}</td><td class="num"><b>${Number(r.composite).toFixed(1)}</b></td><td><span class="signal ${r.signal.toLowerCase()}">${esc(r.signal)}</span></td></tr>`).join('')}
$('#run-forward').onclick=()=>{if(!valid())return toast('Fix configuration weights and signal cutoffs before predicting');const missing=Object.keys(schema).filter(kind=>!forwardUploads[kind]);if(missing.length){$('#forward-message').textContent=`Upload all three files first: ${missing.map(kind=>schema[kind].label).join(', ')} data is missing.`;return toast('Upload Fundamental, Technical, and Catalyst data first')}const records=processForwardData();if(!records?.length){forwardRecords=null;renderForwardResults();$('#forward-message').textContent='No ticker/symbol appears in all three files. Use matching ticker values across Fundamental, Technical, and Catalyst data.';return toast('No tickers match across all three files')}forwardRecords=records;$('#forward-message').textContent=`${records.length} ticker${records.length===1?'':'s'} matched across all three input files. Signal scores use the active configuration.`;renderForwardResults();toast(`Generated ${records.length} forward signal${records.length===1?'':'s'}`)};
$('#load-forward-sample').onclick=()=>{forwardUploads=Object.fromEntries(Object.entries(samples).map(([kind,data])=>[kind,{name:`${kind}-sample.csv`,data}]));forwardRecords=null;$('#forward-message').textContent='Sample inputs loaded. Run Predict signal to calculate forward signals.';renderForwardUploads();renderForwardResults();toast('Sample inputs loaded for Forward Test')};
renderForwardUploads();

// Analyst media score workflow, isolated from the fundamental/technical model.
const ANALYST_KEY='nanovest-analyst-config-v1';
const analystDefaults={directionWeight:50,priceWeight:50,bearish:45,bullish:55,actualReturnThreshold:1,forwardPeriod:20};
let analystConfig={...analystDefaults,...(()=>{try{return JSON.parse(localStorage.getItem(ANALYST_KEY)||'{}')}catch{return{}}})()};
if(![5,10,20,60].includes(Number(analystConfig.forwardPeriod)))analystConfig.forwardPeriod=20;
let analystUploads={direction:null,price:null},analystRecords=[];
function renderAnalystUploads(){const grid=$('#analyst-upload-grid');grid.innerHTML=[['direction','Direction score'],['price','Price score']].map(([key,label])=>{const file=analystUploads[key];return `<article class="card upload-card"><div class="upload-head"><h3>${label}</h3><span class="tag">${file?'READY':'EMPTY'}</span></div><div class="upload-body"><div class="upload-actions"><label class="file-label" for="analyst-file-${key}">Upload CSV / Excel</label><input id="analyst-file-${key}" class="forward-file-input" type="file" accept=".csv,.xlsx,.xls" data-analyst-kind="${key}"><span class="file-name">${file?esc(file.name):'No file selected'}</span></div>${file?`<div class="preview-title">INPUT PREVIEW · ${Math.max(0,file.data.length-1)} records</div>${preview(file.data)}`:`<p class="muted">Include Ticker and ${key==='direction'?'Direction_Score':'Price_Score'} columns. Optional Date and Actual_Return columns support historical backtests.</p>`}</div></article>`}).join('');$$('[data-analyst-kind]').forEach(input=>input.onchange=handleAnalystFile)}
async function handleAnalystFile(event){const file=event.target.files?.[0],kind=event.target.dataset.analystKind;if(!file)return;try{let data;if(/\.csv$/i.test(file.name))data=parseCsv(await file.text());else{if(!window.XLSX)throw Error('Excel reader could not load. Please use CSV.');const workbook=XLSX.read(await file.arrayBuffer(),{type:'array'});data=XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]],{header:1,defval:''})}if(data.length<2)throw Error('The uploaded file has no score rows.');analystUploads[kind]={name:file.name,data};analystRecords=[];$('#analyst-results').hidden=true;$('#analyst-message').textContent=`${kind==='direction'?'Direction':'Price'} score data loaded.`;renderAnalystUploads();toast(`${kind==='direction'?'Direction':'Price'} score uploaded`)}catch(error){toast(error.message)}}
function analystNumber(value,kind){if(value===undefined||value===null||String(value).trim()==='')return null;const text=String(value).trim().toLowerCase();if(kind==='direction'){if(/bull|positive|buy|up/.test(text))return 75;if(/bear|negative|sell|down/.test(text))return 25;if(/neutral|hold|mixed/.test(text))return 50}const n=Number(text.replace('%',''));if(!Number.isFinite(n))return null;return Math.max(0,Math.min(100,n<0?(n+100)/2:n))}
function analystClass(value){return classifyScore(value,Number(analystConfig.bearish),Number(analystConfig.bullish))}
function generateAnalystRecords(){if(!analystUploads.direction||!analystUploads.price)return null;const dirs=rowsAsObjects(analystUploads.direction.data),prices=rowsAsObjects(analystUploads.price.data);const getTicker=r=>String(r.ticker||r.symbol||'').trim().toUpperCase();const scoreFor=(r,kind)=>analystNumber(kind==='direction'?(r.direction_score??r.score??r.signal):(r.price_score??r.score??r.signal),kind);const index=new Map();for(const r of prices){const t=getTicker(r);if(t)index.set(`${t}|${String(r.date||'').trim()}`,r)}const out=[];for(const d of dirs){const ticker=getTicker(d);if(!ticker)continue;const date=String(d.date||'').trim(),p=index.get(`${ticker}|${date}`)||index.get(`${ticker}|`)||prices.find(x=>getTicker(x)===ticker);if(!p)continue;const direction=scoreFor(d,'direction'),price=scoreFor(p,'price');if(direction===null||price===null)continue;const composite=weightedComposite([direction,price],[Number(analystConfig.directionWeight),Number(analystConfig.priceWeight)]);const rawActual=d.actual_return??d.actual_return_percent??d.return??p.actual_return??p.actual_return_percent??p.return;const actual=rawActual==null||String(rawActual).trim()===''?null:Number(String(rawActual).replace('%',''));const threshold=Number(analystConfig.actualReturnThreshold);const actualSignal=actual===null||!Number.isFinite(actual)?null:actualDirection(actual,threshold);const signal=analystClass(composite);out.push({date:date||String(p.date||''),ticker,direction,price,composite,signal,actual:Number.isFinite(actual)?actual:null,actualDirection:actualSignal,correct:actualSignal!==null&&signal===actualSignal})}return out.sort((a,b)=>(b.date||'').localeCompare(a.date||'')||a.ticker.localeCompare(b.ticker))}
function renderAnalystResults(){const records=analystRecords,panel=$('#analyst-results');if(!records.length){panel.hidden=true;return}panel.hidden=false;const historical=records.filter(r=>r.actual!==null),correct=historical.filter(r=>r.correct).length;$('#analyst-metrics').innerHTML=[['Predictions',records.length,'Matched direction and price score rows'],['Bullish',records.filter(r=>r.signal==='Bullish').length,'Configured bullish threshold'],['Bearish',records.filter(r=>r.signal==='Bearish').length,'Configured bearish threshold'],['Backtest accuracy',historical.length?`${Math.round(correct/historical.length*100)}%`:'—',historical.length?`${correct} / ${historical.length} matched actual directions`:'Add Actual_Return values for backtest results']].map(x=>`<div class="card metric"><span>${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('');$('#analyst-count').textContent=`${records.length} predictions`;$('#analyst-body').innerHTML=records.map(r=>`<tr><td><b>${esc(r.ticker)}</b></td><td class="num">${r.direction.toFixed(1)}</td><td class="num">${r.price.toFixed(1)}</td><td class="num"><b>${r.composite.toFixed(1)}</b></td><td><span class="signal ${r.signal.toLowerCase()}">${r.signal}</span></td></tr>`).join('')}
$('#run-analyst').onclick=()=>{if(!analystUploads.direction||!analystUploads.price)return toast('Upload both Direction score and Price score files first');if(Number(analystConfig.directionWeight)+Number(analystConfig.priceWeight)!==100||Number(analystConfig.bearish)>=Number(analystConfig.bullish)||!Number.isFinite(Number(analystConfig.actualReturnThreshold))||Number(analystConfig.actualReturnThreshold)<0||!Number.isInteger(Number(analystConfig.forwardPeriod))||Number(analystConfig.forwardPeriod)<1||Number(analystConfig.forwardPeriod)>10000)return toast('Save a valid Analyst configuration first');analystRecords=generateAnalystRecords()||[];renderAnalystResults();if(!analystRecords.length){$('#analyst-message').textContent='No matching ticker rows with readable scores. Use matching ticker/symbol values and score columns.';return toast('No matching analyst score rows')}const hist=analystRecords.filter(r=>r.actual!==null).length;$('#analyst-message').textContent=`Generated ${analystRecords.length} predictions${hist?` with ${hist} historical outcomes for backtesting`:'; no Actual_Return values were supplied, so these are forward signals'}.`;toast(`Generated ${analystRecords.length} analyst predictions`)};
function updateAnalystConfig(){const total=Number(analystConfig.directionWeight)+Number(analystConfig.priceWeight),ok=total===100&&Number(analystConfig.bearish)>=0&&Number(analystConfig.bearish)<Number(analystConfig.bullish)&&Number(analystConfig.bullish)<=100&&Number.isFinite(Number(analystConfig.actualReturnThreshold))&&Number(analystConfig.actualReturnThreshold)>=0&&Number.isInteger(Number(analystConfig.forwardPeriod))&&Number(analystConfig.forwardPeriod)>=1&&Number(analystConfig.forwardPeriod)<=10000;$('#analyst-total').textContent=`Total ${total}%`;$('#analyst-total').className=`status ${ok?'good':'bad'}`;if(analystRecords.length){analystRecords=generateAnalystRecords()||[];renderAnalystResults()}}
for(const [id,key] of [['direction-weight','directionWeight'],['price-weight','priceWeight'],['analyst-bearish','bearish'],['analyst-bullish','bullish'],['analyst-actual-threshold','actualReturnThreshold']]){$(`#${id}`).value=analystConfig[key];$(`#${id}`).onchange=e=>{analystConfig[key]=Number(e.target.value);updateAnalystConfig()}}
const analystForwardSelect=$('#analyst-forward-period');analystForwardSelect.value=String(analystConfig.forwardPeriod);analystForwardSelect.onchange=e=>{analystConfig.forwardPeriod=Number(e.target.value);updateAnalystConfig()};
$('#save-analyst-config').onclick=()=>{const total=Number(analystConfig.directionWeight)+Number(analystConfig.priceWeight);if(total!==100||analystConfig.bearish<0||analystConfig.bearish>=analystConfig.bullish||analystConfig.bullish>100||!Number.isFinite(Number(analystConfig.actualReturnThreshold))||analystConfig.actualReturnThreshold<0||!Number.isInteger(Number(analystConfig.forwardPeriod))||analystConfig.forwardPeriod<1||analystConfig.forwardPeriod>10000)return toast('Set weights to 100%, keep bearish below bullish, and enter a valid return threshold and forward period');localStorage.setItem(ANALYST_KEY,JSON.stringify(analystConfig));toast('Analyst configuration saved in this browser')};
renderAnalystUploads();updateAnalystConfig();
